package main

import (
	"fmt"
	"os"
	"sort"
	"strconv"
	"strings"
)

// Four more of the oracle/ emitter family. As in oracleemitters.go, the HEADER text IS the
// product: every byte below is output that `task data-regen -- --check` compares against what is
// committed, so a reflowed sentence is a diff.

// ------------------------------------------------------------------- skill-minion-lists

const oeMinionListsHeader = `package raw

// CODE GENERATED BY oracle/skill_minion_lists_emit.py FROM PoB %s. DO NOT EDIT.
// Regenerate with ` + "`task data-regen -- --only minion-lists`" + ` after a PoB pin bump.

// SkillMinionLists and SupportAddMinionLists mirror the ` + "`minionList`" + ` / ` +
	"`addMinionList`" + ` fields of
// PoB's hand-written skill data (src/Data/Skills/*.lua), keyed by granted-effect id.
//
// Neither comes from extracted game data — they are PoB tables, which is why the
// whole minion-limit family (ActiveGolemLimit, ActiveSkeletonLimit, …) resolved to nothing here
// until they were ported. CalcActiveSkill.lua:505-543 walks minionList to pick a minion type and
// then reads data.minions[type].limit; CalcPerform.lua:1261-1263 sums that mod name off the
// skill's own mod list and writes it to output under the same name.
//
// RaiseSpectre's entry is PRESENT AND EMPTY, which is not the same as absent and is why every
// read of this map must use the two-value form. An empty minionList is PoB's signal to
// substitute build.spectreList and set isSpectre (CalcActiveSkill.lua:506-516); an ABSENT entry
// means the skill summons nothing and takes the ` + "`minionList = { }`" + ` arm at :515. A Go nil slice
// cannot tell those apart, so the ok flag carries the distinction.
//
// ⚠️ THE SLICE ORDER IS PoB's AND MUST STAY SO. CalcActiveSkill.lua:505-543 walks this list to
// choose a minion type; a reordering picks a different one and every minion value diverges with
// no value gate able to say why.
`

const oeMinionListsAddDoc = `
// SupportAddMinionLists mirrors ` + "`addMinionList`" + `, which CalcActiveSkill.lua reads off a SUPPORT
// rather than an active skill: the support only ever supplies the chosen minion type when the
// supported skill summons nothing itself.`

func oeEmitMinionMap(name string, rows, locs map[string]any) []string {
	out := []string{fmt.Sprintf("var %s = map[string][]string{", name)}
	for _, skillID := range oeSortedKeys(rows) {
		ids := oeArray(rows[skillID])
		if loc, ok := locs[skillID]; ok && oeTruthy(loc) {
			note := ""
			if len(ids) == 0 {
				note = " — the only empty one in src/."
			}
			out = append(out, "\t// "+oeStr(loc)+note)
		}
		quoted := make([]string, len(ids))
		for i, v := range ids {
			quoted[i] = oeGoStr(oeStr(v))
		}
		out = append(out, fmt.Sprintf("\t%s: {%s},", oeGoStr(skillID), strings.Join(quoted, ", ")))
	}
	return append(out, "}")
}

func oracleSkillMinionListsEmit(argv []string) int {
	if len(argv) != 2 {
		return oeUsage("usage: skill_minion_lists_emit.py <dump.json> <out.go>")
	}
	dump, rc := oeLoadDump(argv[0])
	if rc != 0 {
		return rc
	}
	// REFUSE rather than emit a plausible empty file. An empty SkillMinionLists compiles and
	// turns every summoning skill in the corpus into one that summons nothing -- silently.
	if !oeTruthy(dump["minionList"]) {
		return oeRefuse("the dump has no minionList entries. Re-run oracle/skill_minion_fields.lua.")
	}
	if !oeTruthy(dump["addMinionList"]) {
		return oeRefuse("the dump has no addMinionList entries. PoB has carried exactly one " +
			"(SupportSummonGhostOnKill) since 2.18.1; zero means the field was renamed and the " +
			"dumper is looking for something that no longer exists.")
	}
	lists := oeObject(dump["minionList"])
	adds := oeObject(dump["addMinionList"])
	locs := oeObject(dump["locs"])

	lines := make([]string, 0, len(lists)*2+len(adds)*2+8)
	lines = append(lines, fmt.Sprintf(oeMinionListsHeader, oeVersion(dump)))
	lines = append(lines, oeEmitMinionMap("SkillMinionLists", lists, locs)...)
	lines = append(lines, oeMinionListsAddDoc)
	lines = append(lines, oeEmitMinionMap("SupportAddMinionLists", adds, locs)...)
	lines = append(lines, "")
	lines = append(lines,
		"// The `limit` field itself lives on Minions (minion_data.go) alongside the rest of",
		"// src/Data/Minions.lua. It used to be a standalone MinionLimits map holding 19 entries",
		"// and nothing else, because the limit was the only field anything here could consume.")
	lines = append(lines, "")

	if rc := oeWriteGo(argv[1], strings.Join(lines, "\n")); rc != 0 {
		return rc
	}
	var empty []string
	for k, v := range lists {
		if !oeTruthy(v) {
			empty = append(empty, k)
		}
	}
	sort.Strings(empty)
	joined := strings.Join(empty, ", ")
	if joined == "" {
		joined = "none"
	}
	fmt.Fprintf(os.Stderr, "wrote %s: %d minionList (%d empty: %s), %d addMinionList\n",
		argv[1], len(lists), len(empty), joined, len(adds))
	return 0
}

// --------------------------------------------------------------- skill-hidden-levels

const oeHiddenLevelsHeader = `package raw

// CODE GENERATED BY oracle/skill_hidden_levels_emit.py FROM PoB %s. DO NOT EDIT.
// Regenerate with ` + "`task data-regen -- --only skill-hidden-levels`" + ` after a PoB pin bump.
//
// SkillHiddenLevels carries the ` + "`stats`" + `, ` + "`skillTypes`" + ` and ` + "`levels`" + ` blocks of PoB's HIDDEN
// skills — the src/Data/Skills entries the export pass never regenerates because GGG's data
// has no per-level rows for them.
//
// WHY IT IS NEEDED SEPARATELY FROM SkillStatMaps AND SkillBaseMods. Those two say what a stat
// MEANS and what a skill carries unconditionally; neither supplies a stat's VALUE. The value
// comes from the granted effect's level rows, and for a hidden skill there are none:
// CalculatedGrantedEffect.calculate takes the "no rows" seed at granted_effects.go and
// produces an empty stat list against an empty Values slice. The stat map is then never
// consulted, because there is no stat to consult it for.
//
// That is a DIFFERENT failure from the one pobOnlyGrantedEffects covers. There the whole
// poe.GrantedEffect is missing and the skill is never built; here go-pob-data HAS the granted
// effect and the skill IS built, just with nothing in it.
//
// MEASURED POPULATION: the hidden skills reached from a corpus build's minion skill list whose
// PoB definition carries a nonempty ` + "`stats`" + ` block. The hidden skills with
// ` + "`levels = { [1] = { cost = { } } }`" + ` and no stats — InfernalLegion, MinionInstability —
// need no entry, which is why they are absent rather than empty.
//
// ⚠️ THE TAIL IS MEASURED, NOT ASSUMED. calculator/empty_skill_data_census_test.go enumerates
// PoB's WHOLE hand-written skill table against what GetCalculatedGrantedEffect produces, and
// SIZES each row by walking the built environment of every corpus build. Re-run it rather than
// reading a count off this comment:
//
//	task empty-skill-data
//
// A row belongs here when its BUILDS column is nonzero — that column, not the row's existence,
// is what makes one a defect. The id list is declared in oracle/skill_hidden_levels.lua.
//
//pob:src/Data/Skills/spectre.lua
var SkillHiddenLevels = map[string]HiddenSkill{
`

const oeHiddenLevelsFooter = `}

// HiddenSkill is one entry of SkillHiddenLevels. Values are positional against Stats, exactly
// as PoB's ` + "`levels[n] = { ... }`" + ` array is positional against its ` + "`stats`" + ` list.
//
// Only the stat values are carried. The other level fields PoB writes on these entries
// (duration, cooldown, cost) are omitted because nothing reads them for a skill that exists
// solely to publish a GlobalEffect buff — the buff merge in CalcPerform never consults them.
//
// ⚠️ A LEVEL ROW SHORTER THAN Stats IS PoB'S OWN SHAPE, NOT A TRUNCATED DUMP. ` + "`level[index] or" + `
// 1` + "`" + ` (src/Modules/CalcTools.lua:166) supplies the tail, and calc_tools.go ports that fallback,
// so a trailing stat with no value is deliberately left unwritten rather than filled with a
// literal.
type HiddenSkill struct {
	// SkillTypes is PoB's ` + "`skillTypes`" + ` block. go-pob normally derives the set from
	// go-pob-data's ActiveSkillTypes, which is empty for a hidden skill.
	SkillTypes []string
	Stats      []string
	Levels     map[int][]float64
}
`

func oracleSkillHiddenLevelsEmit(argv []string) int {
	if len(argv) != 2 {
		return oeUsage("usage: skill_hidden_levels_emit.py <dump.json> <out.go>")
	}
	dump, rc := oeLoadDump(argv[0])
	if rc != 0 {
		return rc
	}
	// REFUSE rather than emit a plausible empty table. An empty SkillHiddenLevels compiles and
	// silently restores exactly the defect this table was written to repair.
	if !oeTruthy(dump["order"]) || !oeTruthy(dump["entries"]) {
		return oeRefuse("the dump has no entries. Re-run oracle/skill_hidden_levels.lua.")
	}
	order := oeArray(dump["order"])
	entries := oeObject(dump["entries"])

	lines := []string{fmt.Sprintf(oeHiddenLevelsHeader, oeVersion(dump))}
	stats, levelRows := 0, 0
	for _, sidAny := range order {
		sid := oeStr(sidAny)
		e := oeObject(entries[sid])
		if !oeTruthy(e["stats"]) || !oeTruthy(e["levels"]) {
			return oeRefuse(fmt.Sprintf("%s came back with no stats or no levels.", sid))
		}
		// python splits an ABSENT note as "" -> [""] -> one bare "//" line, which is a real part
		// of the output rather than a skipped branch.
		note := ""
		if v, ok := e["note"]; ok && oeTruthy(v) {
			note = oeStr(v)
		}
		for _, para := range strings.Split(note, "\n") {
			if para == "" {
				lines = append(lines, "\t//")
			} else {
				lines = append(lines, "\t// "+para)
			}
		}
		lines = append(lines, fmt.Sprintf("\t%s: {", oeGoStr(sid)))
		if oeTruthy(e["skillTypes"]) {
			types := oeArray(e["skillTypes"])
			quoted := make([]string, len(types))
			for i, t := range types {
				quoted[i] = oeGoStr(oeStr(t))
			}
			lines = append(lines, "\t\tSkillTypes: []string{"+strings.Join(quoted, ", ")+"},")
		}
		lines = append(lines, "\t\tStats: []string{")
		for _, s := range oeArray(e["stats"]) {
			lines = append(lines, fmt.Sprintf("\t\t\t%s,", oeGoStr(oeStr(s))))
			stats++
		}
		lines = append(lines, "\t\t},")
		lines = append(lines, "\t\tLevels: map[int][]float64{")
		levels := oeObject(e["levels"])
		for _, key := range oeKeysSortedByInt(levels) {
			vals := oeArray(levels[key])
			rendered := make([]string, len(vals))
			for i, v := range vals {
				rendered[i] = oeGoNum(v)
			}
			n, _ := strconv.Atoi(key)
			lines = append(lines, fmt.Sprintf("\t\t\t%d: {%s},", n, strings.Join(rendered, ", ")))
		}
		levelRows += len(levels)
		lines = append(lines, "\t\t},")
		lines = append(lines, "\t},")
	}
	lines = append(lines, oeHiddenLevelsFooter)

	if rc := oeWriteGo(argv[1], strings.Join(lines, "\n")); rc != 0 {
		return rc
	}
	fmt.Fprintf(os.Stderr, "wrote %s: %d hidden skills, %d stats, %d level rows\n",
		argv[1], len(order), stats, levelRows)
	return 0
}

// oeKeysSortedByInt is python's `sorted(d, key=int)`: the KEYS are strings in JSON and the order
// is NUMERIC, so "10" follows "9" rather than preceding it.
func oeKeysSortedByInt(m map[string]any) []string {
	keys := oeSortedKeys(m)
	sort.SliceStable(keys, func(i, j int) bool {
		a, aerr := strconv.Atoi(keys[i])
		b, berr := strconv.Atoi(keys[j])
		if aerr != nil || berr != nil {
			return keys[i] < keys[j]
		}
		return a < b
	})
	return keys
}

// ------------------------------------------------------------------- tattoo-passives

const oeTattooHeader = `package data

// Tattoo replacement nodes PoB's src/Data/TattooPassives.lua holds, derived from the game's PassiveSkillOverrides as
// PoB's Export/Scripts/tattooPassives.lua derives them.
//
// CODE GENERATED BY scripts/gopob tattoo-passives-emit FROM %s. DO NOT EDIT.
// Regenerate with ` + "`task data-regen -- --only tattoo-passives`" + ` after a go-pob-data bump.
//
// A tattoo REPLACES a passive node: PassiveSpec.lua:1185-1189 calls ReplaceNode(node,
// hashOverrides[node.id]) for every node the build's <Overrides> names, in the same loop as the
// conquered-node transform and immediately BEFORE it. So a node can be both tattooed and
// conquered, and 541 of 1454 corpus builds carry both.
//
// ⚠️ KEYED BY DISPLAY NAME. The build XML stores ` + "`dn`" + `, not the row's ` + "`id`" + `, and the two differ.
// %s rows scanned in the module.

`

func oeTattooNodeLiteral(row map[string]any, indent, where string) ([]string, int) {
	nodeID, idOK := row["id"].(string)
	dn, dnOK := row["dn"].(string)
	if !idOK || nodeID == "" {
		return nil, oeRefuse(where + " has no id")
	}
	if !dnOK || dn == "" {
		return nil, oeRefuse(fmt.Sprintf("%s (%s) has no `dn`, which is the key the build file "+
			"references it by", where, nodeID))
	}
	out := []string{indent + "ID: " + oeGoStr(nodeID) + ",", indent + "DN: " + oeGoStr(dn) + ","}
	sd := oeArray(row["sd"])
	if len(sd) > 0 {
		out = append(out, indent+"Stats: []string{")
		for _, line := range sd {
			s, ok := line.(string)
			if !ok {
				return nil, oeRefuse(fmt.Sprintf("%s (%s) has a non-string stat line", where, nodeID))
			}
			out = append(out, indent+"\t"+oeGoStr(s)+",")
		}
		out = append(out, indent+"},")
	} else {
		// A real state, not a dump failure — some rows are pure flavour or are ascendancy
		// markers whose only line lives elsewhere. Saying so stops the next reader "fixing" it.
		out = append(out, indent+"Stats: nil, // PoB carries no `sd` for this row")
	}
	return out, 0
}

func oracleTattooPassivesEmit(argv []string) int {
	if len(argv) != 2 {
		return oeUsage("usage: tattoo_passives_emit.py <dump.json> <out.go>")
	}
	dump, rc := oeLoadDump(argv[0])
	if rc != 0 {
		return rc
	}
	nodes := oeObject(dump["nodes"])
	if len(nodes) == 0 {
		//go-only: the dump now comes from scripts/gamedatadump
		return oeRefuse("the dump carries no tattoo rows. Re-run go run ./scripts/gamedatadump tattoo-passives.")
	}
	// The same control the dumper applies, re-checked here so a hand-edited dump cannot slip
	// through: this row is referenced by testdata/corpus-3.29/0001-necromancer-unknown.xml.
	const probe = "Tattoo of the Tawhoa Shaman"
	if _, ok := nodes[probe]; !ok {
		return oeRefuse(fmt.Sprintf("%s is absent from the dump; it is referenced by the corpus, "+
			"so a dump without it is not a dump of the table PoB reads", pyRepr(probe)))
	}

	scanned := "?"
	if v, ok := dump["scanned"]; ok {
		scanned = oeStr(v)
	}
	lines := []string{fmt.Sprintf(oeTattooHeader, oeVersion(dump), scanned)}
	lines = append(lines,
		"// TattooNodes is keyed by the `dn` a build's <Override> element names.",
		"var TattooNodes = map[string]LegionNode{")
	for _, dn := range oeSortedKeys(nodes) {
		lines = append(lines, fmt.Sprintf("\t%s: {", oeGoStr(dn)))
		lit, rc := oeTattooNodeLiteral(oeObject(nodes[dn]), "\t\t",
			fmt.Sprintf("nodes[%s]", pyRepr(dn)))
		if rc != 0 {
			return rc
		}
		lines = append(lines, lit...)
		lines = append(lines, "\t},")
	}
	lines = append(lines, "}", "")

	// ⚠️ EMITTED AS A SEPARATE SET RATHER THAN A LegionNode FIELD. LegionNode is shared with the
	// legion table, where the concept does not exist; widening it would put a field on 381 rows
	// that can only ever be false. The keystone rows are a handful.
	//
	// ⚠️ `overrideType` AND `name` ARE STILL NOT EMITTED, AND THE MEASUREMENT SAYS DO NOT BOTHER.
	// CalcSetup.lua:691-695 publishes one multiplier per allocated tattoo TYPE
	// (`env.modDB.multipliers[type] = count`), which calculator/env.go's mastery-tally comment
	// points here for. Sized 2026-09-19 over all 15224 corpus builds, and it is worth EXACTLY ZERO
	// — a zero of the "the consumer can never fire" kind, not "not graded here":
	//
	//	17 distinct overrideType values in TattooPassives.lua, enumerated FROM THE FILE
	//	  7 have NO consumer anywhere in the pin (KeystoneTattoo 48 rows, AlternateMastery 32,
	//	    UnknownTattoo 29, Honoured{Heart,Mind,Soul}Tattoo, AscendancyTattooShadow)
	//	 10 tribal types DO have consumers — src/Data/Skills/other.lua, the "Spirit of <X>"
	//	    buff skills, as {type="Multiplier", var="<Tribe>Tattoo"}. We already carry every one
	//	    of those statMap entries in data/raw/skill_stat_maps.go, so the CONSUMER half is done
	//	    and only the producer is absent.
	//
	// The gate is what kills it. Each Spirit skill is granted by one specific tattoo, the
	// "Loyalty Tattoo of <X>" row (or by the Honoured Alliance coral ring, Uniques/ring.lua:666).
	// Corpus carriers, counted over every <Override dn="..."> in every build:
	//
	//	any recognised tattoo override        100 builds
	//	a TRIBAL-type tattoo                   92
	//	a Loyalty Tattoo (grants the skill)     0
	//	Honoured Alliance / "of Akoya"          0
	//
	// So all 92 tribal-tattoo builds publish multipliers that nothing on those builds reads.
	// Adding the field is cheap; it just buys nothing until a build carries the grant. If that
	// changes, the shape is a SEPARATE `map[string]string` keyed by `dn`, for the same reason the
	// keystone set above is separate — not a LegionNode field.
	//
	// ⚠️ The population is the thing to re-measure, NOT this conclusion: it moves with the corpus,
	// and a promotion is exactly what would make it non-zero. Re-run the count, do not quote it.
	//
	// ⚠️ AND RE-MEASURE IT WITH *THIS* INSTRUMENT, WHICH IS THE WHOLE VALUE OF THE NOTE: enumerate
	// every `<Override nodeId= dn=>` in every corpus XML and join `dn` against the `dn -> overrideType`
	// map extracted from TattooPassives.lua, identifying the Loyalty rows by matching
	// `Summon Spirit of (\w+)` in each row's `sd` lines, with `assert len(loyalty) == 10` as the
	// control that the enumeration did not silently drop a tribe.
	//
	// ⚠️ DO NOT RE-DERIVE IT WITH `task corpus-grep` OR A BARE `grep -rl`. A tattoo is a PASSIVE-TREE
	// override, and corpus-grep prints its own warning that a 0 there means only "0 in the input XML"
	// and must not be read as "nothing carries this". The first draft of this note cited such a grep
	// beside the 0 as if it were corroboration; it is the one instrument that structurally cannot see
	// the thing being counted, and it was struck. The override enumeration is exhaustive BECAUSE a
	// tattoo enters a build only as an <Override> — the same element passive_spec.go's tattooedNodes
	// and PassiveSpec.lua:168 read — so there is no path by which an allocated tattoo is absent from
	// it. The Honoured Alliance 0 is soundly a text grep, because a unique ring IS item text.
	//
	// The counts are counted across EVERY <Overrides> element rather than the active spec alone, so
	// 100 and 92 are UPPER BOUNDS at the allocation rung. An upper bound of 0 is 0 at every rung
	// below it, which is why the activation rung was not worth buying here.
	//
	// ⚠️ ONE HOLE WAS LEFT OPEN BY THE SWEEP AND IS NOW CLOSED, verified against the pin at pin-3.29:
	// the search for other granters of TriggerSummonedAncestor* ran with `--exclude-dir=TreeData`, so
	// a TREE NODE granting a Spirit skill would have been missed. It is a real mechanism —
	// `Trigger level 20 Summon Spirit of Kaom Skill when a Totem dies ...` appears in 8 tree files —
	// but ONLY in the `*_alternate` and `*_ruthless_alternate` trees of 3_25 through 3_28.
	// src/TreeData/3_29/tree.lua and 3_29_ruthless/tree.lua both carry ZERO occurrences, and
	// "Loyalty Tattoo" appears in no tree file at all. So no 3.29 tree node grants the skill and the
	// zero is closed on the tree-sourced path too.
	var keystones []string
	for dn, row := range nodes {
		if oeTruthy(oeObject(row)["isKeystone"]) {
			keystones = append(keystones, dn)
		}
	}
	sort.Strings(keystones)
	lines = append(lines,
		"// TattooKeystones are the rows PoB marks `ks`. ReplaceNode (:1630) copies keystoneMod,",
		"// so these replace the target's keystone identity, which is resolved by NAME through",
		"// tree.keystoneMap rather than by the stat lines above.",
		"var TattooKeystones = map[string]bool{")
	for _, dn := range keystones {
		lines = append(lines, fmt.Sprintf("\t%s: true,", oeGoStr(dn)))
	}
	lines = append(lines, "}", "")

	targets, rc := oeTattooTargets(nodes)
	if rc != 0 {
		return rc
	}
	lines = append(lines, targets...)

	if rc := oeWriteGo(argv[1], strings.Join(lines, "\n")); rc != 0 {
		return rc
	}
	fmt.Fprintf(os.Stderr, "wrote %s (%d tattoos, %d keystone rows)\n",
		argv[1], len(nodes), len(keystones))
	return 0
}

// oeTattooTargets is what the tattoo popup filters and shows per row (TreeTab.lua:846-878), as a set
// beside TattooNodes for the same reason as TattooKeystones: LegionNode is the legion table's too.
func oeTattooTargets(nodes map[string]any) ([]string, int) {
	lines := []string{
		"// TattooTargets is what the tattoo popup filters and shows (TreeTab.lua:846-878), keyed like TattooNodes.",
		"var TattooTargets = map[string]TattooTarget{",
	}
	for _, dn := range oeSortedKeys(nodes) {
		row := oeObject(nodes[dn])
		targetType, ok := row["targetType"].(string)
		if !ok {
			//go-only: the editor fields came after the python original was deleted
			return nil, oeRefuse(fmt.Sprintf("nodes[%s] has no targetType. Re-run go run ./scripts/gamedatadump tattoo-passives.", pyRepr(dn)))
		}
		lines = append(lines, fmt.Sprintf("\t%s: {", oeGoStr(dn)),
			"\t\tTargetType: "+oeGoStr(targetType)+",")
		if v := oeStr(row["targetValue"]); v != "" && v != "None" {
			lines = append(lines, "\t\tTargetValue: "+oeGoStr(v)+",")
		}
		if n := oeIntStr(row["MinimumConnected"]); n != "0" && n != "None" {
			lines = append(lines, "\t\tMinimumConnected: "+n+",")
		}
		if oeTruthy(row["legacy"]) {
			lines = append(lines, "\t\tLegacy: true,")
		}
		if rt := oeArray(row["reminderText"]); len(rt) > 0 {
			lines = append(lines, "\t\tReminderText: "+oeGoStr(oeStr(rt[0]))+",")
		}
		for _, f := range [][2]string{{"Icon", "icon"}, {"ActiveEffectImage", "activeEffectImage"}} {
			if v := oeStr(row[f[1]]); v != "" && v != "None" {
				lines = append(lines, "\t\t"+f[0]+": "+oeGoStr(v)+",")
			}
		}
		lines = append(lines, "\t},")
	}
	return append(lines, "}", ""), 0
}

// ----------------------------------------------------------------- skill-weapon-types

// oeWeaponTypesKnown is PoB's src/Modules/Data.lua:205-221 weaponTypeInfo keys. A weaponTypes key
// outside this set would be dead in PoB too, but an unexpected one means the skill data changed
// shape and the reader should hear about it rather than have it silently emitted into Go as an
// unresolvable string.
var oeWeaponTypesKnown = map[string]bool{
	"None": true, "Bow": true, "Claw": true, "Dagger": true, "Staff": true, "Wand": true,
	"One Handed Axe": true, "One Handed Mace": true, "One Handed Sword": true, "Sceptre": true,
	"Thrusting One Handed Sword": true, "Fishing Rod": true,
	"Two Handed Axe": true, "Two Handed Mace": true, "Two Handed Sword": true,
}

const oeWeaponTypesHeader = `package raw

// SkillWeaponTypes mirrors the ` + "`weaponTypes`" + ` tables of PoB's hand-written skill data
// (src/Data/Skills/*.lua), keyed by granted-effect id. Values are PoB's OWN weapon-type names
// -- src/Modules/Data.lua:205-221's ` + "`weaponTypeInfo`" + ` keys, which data.ItemClassName transcribes
// verbatim -- NOT go-pob-data's plural ItemClasses.
//
// CalcActiveSkill.lua:229-254 collects the active gem's table plus every support gem's, then
// getWeaponFlags (:143-174) rejects a weapon absent from ANY of them by returning a nil flag set
// beside a non-nil info. That pair is what :250 tests to disable the skill; without the table
// the pair can never occur and the arm is unreachable.
//
// ABSENT means "no restriction" and is NOT the same as an empty list: Lua's ` + "`{ ge.weaponTypes }`" + `
// collapses a nil to a zero-length list so :149's ipairs never runs, whereas a present-but-empty
// table would iterate once and reject every weapon. Reading a missing key out of this map yields
// a nil slice, and calculator.getWeaponFlags skips empty lists for exactly that reason.
//
// GENERATED by ` + "`gopob skill-weapon-types-emit`" + ` from scripts/gamedatadump skill-weapon-types: a support's
// GrantedEffects.WeaponRestrictions, an active skill's ActiveSkills.WeaponRestrictions, mapped as PoB's
// Export/Scripts/skills.lua maps them. Regenerate with ` + "`task data-regen -- --only skill-weapon-types`" + `.
// %d of %d skills declare weaponTypes -- %d active, %d support.
var SkillWeaponTypes = map[string][]string{
`

// oracleSkillWeaponTypesEmit reads the dump on STDIN and writes the Go to STDOUT — the one member
// of this family fed through a pipe, because the machine's python3 has no zlib.
func oracleSkillWeaponTypesEmit(argv []string) int {
	// ⚠️ NO ARGUMENT CHECK, BECAUSE THE ORIGINAL HAS NONE. It reads stdin unconditionally and
	// ignores argv, so adding a usage error here would make the two disagree on every stray
	// argument — a divergence invented by the port rather than inherited from it.
	//go-only: task data-regen passes <dump.json> <out.go>; any other argv keeps the pipe
	if len(argv) == 2 {
		dump, rc := oeLoadDump(argv[0])
		if rc != 0 {
			return rc
		}
		var out strings.Builder
		if rc := oeSkillWeaponTypes(dump, &out); rc != 0 {
			return rc
		}
		return oeWriteGo(argv[1], out.String())
	}
	dump, rc := oeLoadStdin("the dump on stdin")
	if rc != 0 {
		return rc
	}
	var out strings.Builder
	if rc := oeSkillWeaponTypes(dump, &out); rc != 0 {
		return rc
	}

	fmt.Print(out.String())
	return 0
}

// oeSkillWeaponTypes writes the table for dump into out, or refuses.
func oeSkillWeaponTypes(dump map[string]any, out *strings.Builder) int {
	// ⚠️ `dump["skills"]` WAS A BARE SUBSCRIPT: a dump without the key is a KeyError traceback,
	// which is a refusal spelled in a way no Go port can reproduce.
	skills, ok := dump["skills"].(map[string]any)
	if !ok {
		return oeRefuse("the dump on stdin has no `skills` object. Regenerate with " +
			"`task pob-skill-table`.")
	}
	rows := map[string]any{}
	for k, v := range skills {
		row, isObj := v.(map[string]any)
		if !isObj {
			continue
		}
		if wt, present := row["weaponTypes"]; present && wt != nil {
			rows[k] = row
		}
	}
	if len(rows) == 0 {
		// An instrument that cannot answer must REFUSE, never return empty: an emitter that
		// writes a valid empty map on a dump predating the weaponTypes field would silently
		// revert the port to its unreachable-arm state, and the Go would still compile.
		return oeRefuse("no skill in the dump carries weaponTypes. Either the dump predates " +
			"oracle/skill_table.lua's weaponTypes field or it is not a PoB skill table. " +
			"Regenerate with `task pob-skill-table`.")
	}

	unknownSet := map[string]bool{}
	for _, v := range rows {
		for _, w := range oeArray(oeObject(v)["weaponTypes"]) {
			s := oeStr(w)
			if !oeWeaponTypesKnown[s] {
				unknownSet[s] = true
			}
		}
	}
	if len(unknownSet) > 0 {
		unknown := make([]string, 0, len(unknownSet))
		for s := range unknownSet {
			unknown = append(unknown, s)
		}
		sort.Strings(unknown)
		// ⚠️ EXIT 4, NOT 3, AND THE DISTINCTION IS THE POINT. A stale dump (3) and a MOVED
		// NAMESPACE (4) are acted on differently: the second means every restricted skill is
		// about to be disabled.
		return oeRefuseWith(4, fmt.Sprintf("weaponTypes names not in PoB's weaponTypeInfo: %s. "+
			"An unresolvable name disables EVERY skill declaring it -- fix the mapping "+
			"rather than emitting it.", pyReprValue(unknown)))
	}

	nSupport := 0
	for _, v := range rows {
		if oeTruthy(oeObject(v)["support"]) {
			nSupport++
		}
	}
	// Total skills in the dump, so the header reports a RATIO rather than a hardcoded 912 --
	// that literal was PoB v2.18.1's count and silently became wrong at the 3.20 pin bump.
	fmt.Fprintf(out, oeWeaponTypesHeader, len(rows), len(skills), len(rows)-nSupport, nSupport)
	for _, skillID := range oeSortedKeys(rows) {
		row := oeObject(rows[skillID])
		names := oeArray(row["weaponTypes"])
		quoted := make([]string, len(names))
		for i, w := range names {
			// ⚠️ A BARE `"%s"`, NOT A JSON-ESCAPED LITERAL. The original interpolates the name
			// directly, so a quote or backslash in it would produce broken Go — and the KNOWN
			// set above is what makes that unreachable. Reproduced rather than hardened.
			quoted[i] = `"` + oeStr(w) + `"`
		}
		if loc, ok := row["loc"]; ok && oeTruthy(loc) {
			fmt.Fprintf(out, "\t// %s\n", oeStr(loc))
		}
		// A bare interpolation here too, for the same reason as the names above.
		fmt.Fprintf(out, "\t\"%s\": {%s},\n", skillID, strings.Join(quoted, ", "))
	}
	out.WriteString("}\n")
	fmt.Fprintf(os.Stderr, "emit: %d skills with weaponTypes (%d active, %d support)\n",
		len(rows), len(rows)-nSupport, nSupport)
	return 0
}
